describe('\u51FD\u6570csvArrayToObjects', () => {
  test('\u8F93\u5165\u7A7A\u6570\u7EC4\u5E94\u8BE5\u8FD4\u56DE\u7A7A\u6570\u7EC4', () => {
    const arr = [];
    const result = csvArrayToObjects(arr);
    expect(result).toEqual([]);
  });

  test('\u8F93\u5165\u6570\u7EC4\u53EA\u6709\u4E00\u884C\u6570\u636E\uFF0C\u5E94\u8BE5\u8FD4\u56DE\u7A7A\u6570\u7EC4', () => {
    const arr = [['key1', 'key2']];
    const result = csvArrayToObjects(arr);
    expect(result).toEqual([]);
  });

  test('\u5E94\u8BE5\u8F6C\u6362csv\u6570\u7EC4\u4E3A\u5BF9\u8C61\u6570\u7EC4', () => {
    const arr = [
      ['key1', 'key2'],
      ['value1', 'value2'],
      ['value3', 'value4'],
    ];
    const result = csvArrayToObjects(arr);
    expect(result).toEqual([
      { key1: 'value1', key2: 'value2' },
      { key1: 'value3', key2: 'value4' },
    ]);
  });

  test('\u8F6C\u6362\u65F6\u5E94\u8BE5\u652F\u6301\u547D\u540D\u6620\u5C04\u8868', () => {
    const arr = [
      ['\u540D\u5B57', '\u5E74\u9F84'],
      ['\u5C0F\u660E', '25'],
      ['\u5C0F\u7EA2', '30'],
    ];
    const renameMap = {
      \u540D\u5B57: 'name',
      \u5E74\u9F84: 'age',
    };
    const result = csvArrayToObjects(arr, renameMap);
    expect(result).toEqual([
      { name: '\u5C0F\u660E', age: '25' },
      { name: '\u5C0F\u7EA2', age: '30' },
    ]);
  });
});
